{"concepto": "Trayectoria (trajectory)", "enunciado": "$\\tau=(s_0,a_0,s_1,\\ldots,s_T)$", "problema": "Representar secuencia de decisión con estados y acciones para análisis retroactivo", "limite": "", "patron": "Registro temporal de pares estado-decisión que permite auditar y evaluar cada paso específico de una interacción", "linea": 130}
{"concepto": "Verificador (verifier)", "enunciado": "$V(\\tau)$ retorna recompensa según estado final o proceso completo", "problema": "Automatizar evaluación de corrección sin juicio humano en cada trayectoria", "limite": "Puede tener false positives y false negatives; validador incorrecto invalida toda la señal (línea 134)", "patron": "Función que traduce ejecución completa a señal binaria o graduada, permitiendo juicio programático desacoplado del entrenamiento", "linea": 130}
{"concepto": "Probabilidad de cobertura por muestreo múltiple (best-of-N)", "enunciado": "Probabilidad de al menos una solución correcta en $N$ intentos independientes: $1-(1-p)^N$ donde $p$ es tasa de éxito individual", "problema": "Cuantificar ganancia de generar múltiples candidatos versus una única respuesta", "limite": "Asume independencia de muestras; en realidad están correlacionadas por política común; selector imperfecto reduce ganancia (línea 216)", "patron": "Composición de eventos independientes; la ganancia de cobertura requiere tanto alta densidad de soluciones como selector confiable", "linea": 216}
{"concepto": "Ejes de calidad de benchmark (hardness, diversity, separability)", "enunciado": "Hardness: tarea ni trivial ni imposible; Diversity: cobertura de ambientes y estrategias variadas; Separability: discrimina modelos con capacidades diferentes", "problema": "Definir propiedades de dataset que hacen benchmark útil para iteración de investigación", "limite": "", "patron": "Descomposición ortogonal de propiedades en dimensiones independientes; ninguna dimensión es suficiente; evaluación holística requiere todas", "linea": 152}
{"concepto": "Actualización on-policy (on-policy update)", "enunciado": "Usar datos generados por política actual $\\pi$ para actualizar esa misma $\\pi$", "problema": "Alinear distribución de datos con política siendo optimizada, reduciendo sesgo de distribución", "limite": "Menos eficiente en muestras que off-policy; requiere recolección en línea continua", "patron": "Operación de aprendizaje donde datos provienen del sistema siendo mejorado; mantiene consistencia estadística entre datos y política", "linea": 499}
{"concepto": "Ponderación por importancia off-policy (importance weighting)", "enunciado": "Multiplicar gradientes por ratio $\\frac{p_{\\theta_{new}}(a|s)}{p_{\\theta_{old}}(a|s)}$ para corregir distribución", "problema": "Reutilizar datos históricos de política vieja para entrenar política nueva, mejorando eficiencia muestral", "limite": "Ratios extremos causan varianza alta; importance weighting diverge lejos de política vieja (línea 183)", "patron": "Corrección de sesgo mediante ratio de densidades; permite aprendizaje de datos desacoplados pero requiere restricciones de varianza", "linea": 183}
{"concepto": "Clipping asimétrico de ratio de probabilidades (asymmetric clipping)", "enunciado": "Limitar cambio de política con límites no-simétricos: permitir mayor aumento donde mejora es posible, limitar disminución", "problema": "Controlar magnitud de actualización individual evitando cambios excesivos mientras se mantiene exploración", "limite": "Clipping simétrico bloquea acciones de baja probabilidad valiosas; completamente asimétrico pierde estabilidad (línea 506)", "patron": "Restricción selectiva de cambio relativo usando límites ajustables; permitir movimiento diferenciado según dirección del cambio", "linea": 506}
{"concepto": "Colapso de entropía (entropy collapse)", "enunciado": "Distribución de salida converge a pocas trayectorias de alta recompensa, eliminando diversidad de exploración", "problema": "Detectar convergencia prematura a solución subóptima causada por concentración de probabilidades", "limite": "Alta entropía puede ser ruido; baja entropía puede ser convergencia legítima. Problemático solo en contexto de trade-off con aprendizaje continuo (línea 188)", "patron": "Monitoreo de dispersión de distribución de salida; mantener incertidumbre mínima para permitir redescubrimiento de trayectorias alternativas válidas", "linea": 471}
{"concepto": "SFT ligero (light SFT)", "enunciado": "Ajuste supervisado con muestras diversas y entrenamiento débil que reduce acciones obviamente inútiles sin comprimir distribución de exploración", "problema": "Establecer política inicial viable sin degradar diversidad de estrategias que RL necesita explorar", "limite": "Fuerza del SFT crea trade-off: muy débil no ayuda convergencia; muy fuerte bloquea exploración en RL (línea 436)", "patron": "Inicialización con sesgo débil que apunta hacia basinbución buena pero no converge dentro de él; deja libertad para fase posterior de mejora", "linea": 158}
{"concepto": "Curriculum de dificultad dinámico (difficulty curriculum)", "enunciado": "Ajustar distribución de tareas durante entrenamiento para mantener tasa de éxito en rango óptimo, siendo dificultad relativa a checkpoint actual", "problema": "Maximizar señal de aprendizaje evitando tareas triviales (ya resueltas) o imposibles (sin éxito)", "limite": "Dificultad es relativa a modelo actual; requiere estimar probabilidad de éxito en línea (línea 201)", "patron": "Estrategia de muestreo adaptativo que varía distribución de datos según desempeño; mantiene zona de desarrollo proximal", "linea": 200}
